window.IMGUI_DOCS.guides.push(...[{"id":"visual-pan-zoom","title":"つかんで動かす、拡大して見る。ズームできるキャンバスを作ろう","summary":"地図やステージ配置図を、マウスで移動・拡大できるようにしてみます。図形の座標と画面の座標を分けると、見た目を動かしてもデータはそのまま保てます。","category":"visuals","level":"intermediate","minutes":18,"tags":["キャンバス","ズーム","パン","座標変換"],"related_api":["ImGui::InvisibleButton","ImGui::GetCursorScreenPos","ImGui::IsItemActive","ImDrawList::PushClipRect","ImDrawList::AddLine","ImGui::SetItemKeyOwner"],"related_guides":["custom-widgets","visual-marquee","visual-node-canvas"],"sources":[{"title":"v1.93.0 公開API: 座標・入力・DrawList","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"v1.93.0 公式デモ: Custom Rendering / Canvas / Image Viewer","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui_demo.cpp"}],"sections":[{"title":"まずは「絵の中の座標」と「画面の座標」を分けよう","paragraphs":["ステージ上の木が (100, 80) にあるとして、ズームするたびにその座標を書き換える必要はありません。**画面座標 = キャンバス左上 + パン量 + データ座標 × 倍率**、という変換を描くときだけ行います。","この例は開いているImGuiウィンドウ内で毎フレーム呼びます。C++17の <algorithm> と <cmath> を使います。各コード例はそれぞれ独立して試せます。"],"id":"visual-pan-zoom-section-1"},{"title":"ホイールで拡大、中ボタンで移動してみる","paragraphs":["操作を受け取るのはInvisibleButton()、見た目を描くのはDrawListです。図形を描くだけでは、クリック領域もレイアウト上の高さも作られません。","ホイール操作では、マウスの下にあったデータ座標が同じ位置に残るようにパン量も調整しています。倍率だけ変えると、見たい場所がマウスから逃げてしまいます。","SetItemKeyOwner()でホイールをこのキャンバスへ割り当てています。親ウィンドウのスクロールまで一緒に動かしたくない場面で役立ちます。"],"code":"void ShowZoomCanvas()\n{\n    static ImVec2 pan(40.0f, 40.0f);\n    static float zoom = 1.0f;\n    ImVec2 size(std::max(240.0f, ImGui::GetContentRegionAvail().x), 260.0f);\n    ImVec2 origin = ImGui::GetCursorScreenPos();\n    ImGui::InvisibleButton(\n        \"zoom_canvas\", size, ImGuiButtonFlags_MouseButtonMiddle);\n    ImGuiIO& io = ImGui::GetIO();\n    if (ImGui::IsItemActive() &&\n        ImGui::IsMouseDragging(ImGuiMouseButton_Middle))\n    {\n        pan.x += io.MouseDelta.x;\n        pan.y += io.MouseDelta.y;\n    }\n    if (ImGui::SetItemKeyOwner(ImGuiKey_MouseWheelY) &&\n        io.MouseWheel != 0.0f)\n    {\n        ImVec2 world((io.MousePos.x - origin.x - pan.x) / zoom,\n            (io.MousePos.y - origin.y - pan.y) / zoom);\n        zoom =\n            std::clamp(zoom * std::pow(1.15f, io.MouseWheel), 0.25f, 4.0f);\n        pan = ImVec2(io.MousePos.x - origin.x - world.x * zoom,\n            io.MousePos.y - origin.y - world.y * zoom);\n    }\n    ImVec2 end(origin.x + size.x, origin.y + size.y);\n    ImDrawList* draw = ImGui::GetWindowDrawList();\n    draw->PushClipRect(origin, end, true);\n    draw->AddRectFilled(origin, end, IM_COL32(25, 31, 42, 255));\n    const float step = 64.0f * zoom;\n    for (float x = std::fmod(pan.x, step); x < size.x; x += step)\n        draw->AddLine(ImVec2(origin.x + x, origin.y),\n            ImVec2(origin.x + x, end.y),\n            IM_COL32(70, 80, 98, 180));\n    for (float y = std::fmod(pan.y, step); y < size.y; y += step)\n        draw->AddLine(ImVec2(origin.x, origin.y + y),\n            ImVec2(end.x, origin.y + y),\n            IM_COL32(70, 80, 98, 180));\n    ImVec2 object(\n        origin.x + pan.x + 100.0f * zoom, origin.y + pan.y + 80.0f * zoom);\n    draw->AddCircleFilled(\n        object, 18.0f * zoom, IM_COL32(76, 204, 158, 255));\n    draw->PopClipRect();\n    ImGui::Text(\"Zoom %.2fx / middle drag to pan\", zoom);\n}","id":"visual-pan-zoom-section-2","capture":{"guide_id":"visual-pan-zoom","section_index":1,"scene":"example-visual-pan-zoom-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"117ba6c79eb4a1e927114559c8d3dd0783d2411389ff5795fa88800b06c3c2cd","image_sha256":"5a83a1e3797f312ec20d2779e3762e3718f7cdaed3a218ab83bf3dd9dbf309e9","fixture":"ShowZoomCanvas();","initialization":""}},{"title":"クリックした場所をデータ座標へ戻す","paragraphs":["配置ツールでは逆変換も必要です。次の例では左クリックした点を0〜320、0〜180のキャンバス座標として保持します。スクリーン座標を保存すると、ウィンドウを動かしただけで配置がずれるので気をつけましょう。"],"code":"void ShowCanvasPick()\n{\n    static ImVec2 point(160.0f, 90.0f);\n    const float scale = 1.25f;\n    ImVec2 origin = ImGui::GetCursorScreenPos();\n    ImGui::InvisibleButton(\"canvas_pick\", ImVec2(400.0f, 225.0f));\n    if (ImGui::IsItemClicked())\n    {\n        ImVec2 mouse = ImGui::GetIO().MousePos;\n        point = ImVec2(\n            (mouse.x - origin.x) / scale, (mouse.y - origin.y) / scale);\n    }\n    ImVec2 end(origin.x + 400.0f, origin.y + 225.0f);\n    ImDrawList* draw = ImGui::GetWindowDrawList();\n    draw->PushClipRect(origin, end, true);\n    draw->AddRectFilled(origin, end, IM_COL32(32, 39, 51, 255));\n    draw->AddCircleFilled(\n        ImVec2(origin.x + point.x * scale, origin.y + point.y * scale),\n        6.0f,\n        IM_COL32(255, 189, 76, 255));\n    draw->PopClipRect();\n    ImGui::Text(\"Data position: %.1f, %.1f\", point.x, point.y);\n}","id":"visual-pan-zoom-section-3","capture":{"guide_id":"visual-pan-zoom","section_index":2,"scene":"example-visual-pan-zoom-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"17391eff0ba7df5026d042ac5975a0be67375ffdeccb414ff406687048612554","image_sha256":"f2841706081979c9948c7dbbd0c813d4c083b8e74e0d31cf10e985984130da38","fixture":"ShowCanvasPick();","initialization":""}},{"title":"見える範囲と、操作できる範囲は別に考える","paragraphs":["PushClipRect()は描画を切り取る指定です。マウス判定を自動で同じ範囲に制限する機能ではありません。キャンバス全体の操作はIsItemHovered()/IsItemActive()、中の物体のヒット判定は変換後の座標で調べます。"],"bullets":["同じウィンドウに複数のキャンバスを置く場合は、それぞれ別のIDを付けます。","倍率の下限を設けると、グリッドの刻みが極小になって線の数が増えすぎるのを防げます。","巨大なマップでは画面外の物体の描画を省きます。クリップだけではCPU側のループ回数は減りません。"],"id":"visual-pan-zoom-section-4"},{"title":"次は配置データを編集するツールへ","paragraphs":["範囲選択・スナップ・Undoを足せば、レベル編集の入り口になります。まずはパンと倍率を表示状態としてまとめ、物体の位置データとは別に保存するところから始めてみてください。","公式デモのCanvasとImage Viewerは、入力領域・クリップ・座標変換を組み合わせる実例です。このガイドでは同じ考え方で小さな配置用キャンバスを組み立てています。"],"id":"visual-pan-zoom-section-5"}],"image":"guide-visual-canvas","image_scene":"example-visual-pan-zoom-02","image_caption":""},{"id":"visual-radar","title":"敵はどっち？ 位置関係がわかるレーダーとミニマップ","summary":"座標の数字だけでは距離感がつかみにくいときに。プレイヤーを中心としたレーダーと、エリア全体を見るミニマップを描き分けてみましょう。","category":"visuals","level":"intermediate","minutes":16,"tags":["レーダー","ミニマップ","2D可視化","座標変換"],"related_api":["ImGui::GetWindowDrawList","ImGui::Dummy","ImDrawList::AddCircle","ImDrawList::AddCircleFilled","ImDrawList::AddRect"],"related_guides":["visual-pan-zoom","visual-hud","custom-widgets"],"sources":[{"title":"v1.93.0 公開API: 座標・入力・DrawList","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"v1.93.0 公式デモ: Custom Rendering / Canvas / Image Viewer","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui_demo.cpp"}],"sections":[{"title":"同じ位置データでも、基準を変えると見え方が変わる","paragraphs":["レーダーはプレイヤーからの相対位置、ミニマップはエリアの最小・最大から求めた位置を使います。**何を中心に見たいか**を先に決めると、式がシンプルになります。","例ではワールドのX/Zを地図の横/縦に使います。地図の上を+Zにしたいので、画面のY方向だけ符号を反転します。<algorithm> と <cmath> を使い、開いているウィンドウ内で呼びます。"],"id":"visual-radar-section-1"},{"title":"プレイヤーを中心にしたレーダー","paragraphs":["範囲外の対象は円の内側へ寄せ、ラベルにOUTを付けます。これは対象の本当の位置ではなく「この方向にいる」という表示です。色だけで範囲内外を区別しないのがポイントです。","DrawListの矩形クリップでは円形に切り取れません。ここでは点の中心を内側へ収めてから描き、背景円からはみ出さないようにしています。"],"code":"void ShowRadar()\n{\n    const ImVec2 player(100.0f, 80.0f);\n    const ImVec2 targets[] = {\n        ImVec2(135, 105), ImVec2(40, 90), ImVec2(230, 30)};\n    const float range = 100.0f;\n    const float radius = 90.0f;\n    ImVec2 p = ImGui::GetCursorScreenPos();\n    ImGui::Dummy(ImVec2(200.0f, 200.0f));\n    ImVec2 center(p.x + 100.0f, p.y + 100.0f);\n    ImDrawList* draw = ImGui::GetWindowDrawList();\n    draw->AddCircleFilled(center, radius, IM_COL32(27, 40, 45, 255));\n    draw->AddCircle(center, radius, IM_COL32(104, 172, 159, 255), 0, 2.0f);\n    draw->AddCircle(center, radius * 0.5f, IM_COL32(61, 93, 87, 255));\n    draw->AddLine(ImVec2(center.x - radius, center.y),\n        ImVec2(center.x + radius, center.y),\n        IM_COL32(61, 93, 87, 255));\n    draw->AddLine(ImVec2(center.x, center.y - radius),\n        ImVec2(center.x, center.y + radius),\n        IM_COL32(61, 93, 87, 255));\n    for (const ImVec2& target : targets)\n    {\n        float dx = target.x - player.x;\n        float dz = target.y - player.y;\n        float distance = std::sqrt(dx * dx + dz * dz);\n        float factor = (radius - 8.0f) / std::max(range, distance);\n        ImVec2 marker(center.x + dx * factor, center.y - dz * factor);\n        bool outside = distance > range;\n        draw->AddCircleFilled(marker,\n            4.0f,\n            outside ? IM_COL32(255, 181, 76, 255)\n                    : IM_COL32(255, 101, 117, 255));\n        if (outside)\n            draw->AddText(ImVec2(marker.x + 6.0f, marker.y),\n                IM_COL32(255, 220, 160, 255),\n                \"OUT\");\n    }\n    draw->AddTriangleFilled(ImVec2(center.x, center.y - 7),\n        ImVec2(center.x - 5, center.y + 5),\n        ImVec2(center.x + 5, center.y + 5),\n        IM_COL32(120, 220, 255, 255));\n    ImGui::TextUnformatted(\"North up / range: 100 world units\");\n}","id":"visual-radar-section-2","capture":{"guide_id":"visual-radar","section_index":1,"scene":"example-visual-radar-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"12e3199d0cb82283f253613c05b117a579c3bdaefc49334d78ca30c4c5ce9ab6","image_sha256":"340af742e2fea49af7470dbfb1830ef32744adeec5ed259587f252b3603877ae","fixture":"ShowRadar();","initialization":""}},{"title":"エリア全体のミニマップに切り替える","paragraphs":["横長のワールドを正方形に無理やり引き伸ばすと、距離感が変わります。次は幅・高さに同じ倍率を使い、余った領域を余白にしています。"],"code":"void ShowMiniMap()\n{\n    const ImVec2 world_size(400.0f, 200.0f);\n    const ImVec2 locations[] = {\n        ImVec2(35, 50), ImVec2(210, 160), ImVec2(370, 80)};\n    ImVec2 p = ImGui::GetCursorScreenPos();\n    ImVec2 panel(300.0f, 200.0f);\n    ImGui::Dummy(panel);\n    const float scale =\n        std::min(panel.x / world_size.x, panel.y / world_size.y);\n    ImVec2 map_size(world_size.x * scale, world_size.y * scale);\n    ImVec2 origin(p.x + (panel.x - map_size.x) * 0.5f,\n        p.y + (panel.y - map_size.y) * 0.5f);\n    ImDrawList* draw = ImGui::GetWindowDrawList();\n    draw->AddRectFilled(\n        p, ImVec2(p.x + panel.x, p.y + panel.y), IM_COL32(20, 25, 34, 255));\n    draw->AddRectFilled(origin,\n        ImVec2(origin.x + map_size.x, origin.y + map_size.y),\n        IM_COL32(46, 64, 58, 255));\n    for (int i = 0; i < 3; ++i)\n    {\n        ImVec2 marker(origin.x + locations[i].x * scale,\n            origin.y + (world_size.y - locations[i].y) * scale);\n        draw->AddCircleFilled(marker, 5.0f, IM_COL32(255, 201, 96, 255));\n    }\n    ImGui::TextUnformatted(\"400 x 200 world units / equal X-Z scale\");\n}","id":"visual-radar-section-3","capture":{"guide_id":"visual-radar","section_index":2,"scene":"example-visual-radar-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"557ab895619dea6a04688569c7c6e8be106f5e9fa0ee6213776409666bbfd773","image_sha256":"bc2b2e395f13e8a336483be6c79efc3a60aec9c866521e4692edbd6619d551a2","fixture":"ShowMiniMap();","initialization":""}},{"title":"位置がずれたら、この順で見直す","paragraphs":["実際のゲームへつなぐときは、原点と向きの取り違えがよく起きます。まずは原点・+X・+Zにテスト用の点を置いて、地図の右・上へ出るか確認してみましょう。"],"bullets":["レーダーの北固定とプレイヤー方向固定は別仕様です。後者は相対位置をプレイヤーの向きの逆角度で回転します。","3DワールドのYは高さに使っているかもしれません。この例のImVec2.yはZの代わりです。","高さの違いは上下矢印や数値で補いましょう。重なっている点を色だけで区別すると見落としやすくなります。"],"id":"visual-radar-section-4"},{"title":"移動範囲やAIの索敵も重ねてみよう","paragraphs":["対象の半径・現在の目的地・索敵方向を同じ変換で重ねると、AIの判断を説明できるデバッグ画面になります。ミニマップをクリックして目的地を変える場合は、逆変換と範囲チェックも追加しましょう。"],"id":"visual-radar-section-5"}],"image":"guide-visual-dashboard","image_scene":"example-visual-radar-02","image_caption":""},{"id":"visual-hud","title":"数字の羅列を卒業。状態がひと目でわかるHUDとダッシュボード","summary":"FPS、メモリー、接続状態。大事な情報を全部同じ文字で並べるより、数値・単位・状態ラベルの役割を分けると読み取りやすくなります。","category":"visuals","level":"intermediate","minutes":13,"tags":["HUD","ダッシュボード","バッジ","状態表示"],"related_api":["ImGui::BeginTable","ImGui::TableNextColumn","ImGui::TextColored","ImGui::ProgressBar","ImGui::SetNextWindowPos","ImGui::SetNextWindowBgAlpha"],"related_guides":["visual-theme","visual-radar","docking-layout"],"sources":[{"title":"v1.93.0 公開API: 座標・入力・DrawList","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"v1.93.0 公式デモ: Custom Rendering / Canvas / Image Viewer","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui_demo.cpp"}],"sections":[{"title":"何をすぐ知りたい画面なのか決める","paragraphs":["デバッグHUDなら、見た人が「今は正常か」「どれが基準を超えたか」を判断できることが大切です。**数値・単位・許容範囲・状態名**をセットにしてみましょう。","このガイドのフレーム時間やメモリーはサンプル値です。ImGuiがアプリのCPU/GPU時間や使用メモリーを自動計測するわけではありません。測った値をUIへ渡します。"],"id":"visual-hud-section-1"},{"title":"3つの指標をカード風にまとめる","paragraphs":["BeginTable()で列幅をそろえるだけでも、計器盤らしく見えます。失敗時は文字でもOVERと示し、バーは現在の割合を補助的に表します。"],"code":"void ShowDashboard(float frame_ms, float memory_mb, bool connected)\n{\n    ImGui::TextUnformatted(\"Runtime overview\");\n    if (ImGui::BeginTable(\"dashboard\",\n            3,\n            ImGuiTableFlags_Borders | ImGuiTableFlags_SizingStretchSame))\n    {\n        ImGui::TableNextRow();\n        ImGui::TableNextColumn();\n        ImGui::TextUnformatted(\"Frame time\");\n        ImGui::Text(\"%.2f ms\", frame_ms);\n        const bool slow = frame_ms > 16.67f;\n        ImGui::TextColored(slow ? ImVec4(1.0f, 0.45f, 0.32f, 1)\n                                : ImVec4(0.35f, 0.85f, 0.55f, 1),\n            \"%s\",\n            slow ? \"OVER 16.67 ms\" : \"WITHIN BUDGET\");\n        ImGui::ProgressBar(std::clamp(frame_ms / 33.33f, 0.0f, 1.0f),\n            ImVec2(-1, 0),\n            \"0 - 33.33 ms\");\n        ImGui::TableNextColumn();\n        ImGui::TextUnformatted(\"Memory\");\n        ImGui::Text(\"%.1f MB\", memory_mb);\n        ImGui::TextUnformatted(\"Budget: 1024 MB\");\n        ImGui::ProgressBar(std::clamp(memory_mb / 1024.0f, 0.0f, 1.0f),\n            ImVec2(-1, 0),\n            \"0 - 1024 MB\");\n        ImGui::TableNextColumn();\n        ImGui::TextUnformatted(\"Connection\");\n        ImGui::TextColored(connected ? ImVec4(0.35f, 0.85f, 0.55f, 1)\n                                     : ImVec4(1.0f, 0.45f, 0.32f, 1),\n            \"%s\",\n            connected ? \"ONLINE\" : \"OFFLINE\");\n        ImGui::TextUnformatted(connected ? \"Telemetry is live\"\n                                         : \"Showing last received values\");\n        ImGui::EndTable();\n    }\n}","id":"visual-hud-section-2","capture":{"guide_id":"visual-hud","section_index":1,"scene":"example-visual-hud-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"1b7e6a8d84d4227e14b60740b8b80a96438c2600336b6eebffa0a5caa5852978","image_sha256":"c163bacf095cf232081bc806e4f8d4424985e4bc8b8c3a56a0c23219969e34cb","fixture":"ShowDashboard(14.2f,384.0f,true);","initialization":""}},{"title":"画面の隅に、触らない小さなHUDを置く","paragraphs":["SetNextWindowPos()はウィンドウの配置、NoInputsは入力を受け取らない指定です。これはゲーム画面の上に置く読み取り専用HUDに向いています。","この関数はほかのBegin()/End()の内側ではなく、NewFrame()とRender()の間で呼びます。MainViewport基準なので、別のOSウィンドウに移したい場合はそのViewportを選ぶ設計が必要です。"],"code":"void ShowCornerHud(float frame_ms, int entities)\n{\n    const ImGuiViewport* viewport = ImGui::GetMainViewport();\n    ImGui::SetNextWindowPos(\n        ImVec2(viewport->WorkPos.x + viewport->WorkSize.x - 12.0f,\n            viewport->WorkPos.y + 12.0f),\n        ImGuiCond_Always,\n        ImVec2(1, 0));\n    ImGui::SetNextWindowBgAlpha(0.82f);\n    const ImGuiWindowFlags flags =\n        ImGuiWindowFlags_NoDecoration | ImGuiWindowFlags_AlwaysAutoResize |\n        ImGuiWindowFlags_NoSavedSettings | ImGuiWindowFlags_NoInputs |\n        ImGuiWindowFlags_NoNav;\n    if (ImGui::Begin(\"Runtime HUD\", nullptr, flags))\n    {\n        ImGui::Text(\"Frame: %.2f ms\", frame_ms);\n        ImGui::Text(\"Entities: %d\", entities);\n        ImGui::TextUnformatted(frame_ms > 16.67f\n                                   ? \"[!] Frame budget exceeded\"\n                                   : \"[OK] Frame budget\");\n    }\n    ImGui::End();\n}","id":"visual-hud-section-3","capture":{"guide_id":"visual-hud","section_index":2,"scene":"example-visual-hud-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"16bb70d0bbf717f72063d83164ce189f78bd4a3bfde06133354056a5634bb57c","image_sha256":"b478ab3865f95edd53f6ac00b88255a667b4cb0d25fe885c3c7b45b8c8356ce1","fixture":"ShowCornerHud(14.2f,128);","initialization":""}},{"title":"色は目印、意味は言葉でも伝える","paragraphs":["赤い文字に気づけても、何をすればよいかまで伝わるとは限りません。「接続なし」「予算超過」などの状態名を添えると、色覚やスクリーンショットの条件に左右されにくくなります。"],"table":{"headers":["見せたいもの","組み合わせる表示","気をつけたいこと"],"rows":[["現在値","大きめの数値と単位","FPSだけでなくmsも見られると原因を追いやすい"],["異常状態","色 + [!] + 状態名","警告だらけになるしきい値は見直す"],["更新停止","最終受信時刻 + STALE","止まった値を現在の値に見せない"],["読み取り専用","説明ラベルや選択可能な文字","無効なボタンを大量に並べない"]]},"id":"visual-hud-section-4"},{"title":"まずはひとつの判断を助ける画面から","paragraphs":["全部の情報を常時表示するより、サマリーを常設し、詳しい履歴や内訳を別パネルへ置くほうが使いやすいことがあります。HUDで異常を見つけたら、対応する詳細へ移れる導線を足してみてください。"],"id":"visual-hud-section-5"}],"image":"guide-visual-dashboard","image_scene":"example-visual-hud-02","image_caption":""},{"id":"visual-time-scrub","title":"波形をなぞって時間を選ぶ。小さなスクラブUIを作ろう","summary":"音やアニメーションの「この瞬間」を調べたいときに。時間を横位置へ置き換えて、ドラッグで再生位置を動かすUIを作ります。","category":"visuals","level":"advanced","minutes":18,"tags":["時間軸","波形","スクラブ","アニメーション"],"related_api":["ImGui::InvisibleButton","ImGui::IsItemActive","ImGui::IsItemDeactivated","ImDrawList::AddPolyline","ImDrawList::AddLine"],"related_guides":["visual-pan-zoom","extensions-imsequencer","edit-commit"],"sources":[{"title":"v1.93.0 公開API: 座標・入力・DrawList","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"v1.93.0 公式デモ: Custom Rendering / Canvas / Image Viewer","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui_demo.cpp"}],"sections":[{"title":"時間も座標に置き換えれば、つまめるようになる","paragraphs":["横軸の左端を0秒、右端をduration秒と決めれば、マウスのX位置から時刻を計算できます。**UIが選ぶ時刻と、実際に音やアニメーションを再生する処理は分けて**考えましょう。","例では音声ファイルを読み込まず、サイン波を合成して形を描きます。<algorithm> と <cmath> を使い、開いているウィンドウ内で呼びます。"],"id":"visual-time-scrub-section-1"},{"title":"波形と再生ヘッドを描いて、ドラッグで動かす","paragraphs":["InvisibleButton()は押し始めたあとにポインターが枠の外へ出てもアクティブ状態を持ちます。その間も時間を更新し、最後に0〜durationへ制限すると端まで操作できます。"],"code":"void ShowWaveScrubber()\n{\n    static float cursor_seconds = 2.0f;\n    const float duration = 10.0f;\n    ImVec2 size(std::max(240.0f, ImGui::GetContentRegionAvail().x), 140.0f);\n    ImVec2 p = ImGui::GetCursorScreenPos();\n    ImGui::InvisibleButton(\"wave_scrub\", size);\n    const bool dragging = ImGui::IsItemActive();\n    if (dragging)\n        cursor_seconds =\n            std::clamp(\n                (ImGui::GetIO().MousePos.x - p.x) / size.x, 0.0f, 1.0f) *\n            duration;\n    ImDrawList* draw = ImGui::GetWindowDrawList();\n    ImVec2 end(p.x + size.x, p.y + size.y);\n    draw->PushClipRect(p, end, true);\n    draw->AddRectFilled(p, end, IM_COL32(26, 32, 43, 255));\n    for (int second = 0; second <= 10; ++second)\n    {\n        float x = p.x + size.x * second / duration;\n        draw->AddLine(\n            ImVec2(x, p.y), ImVec2(x, end.y), IM_COL32(63, 74, 96, 255));\n    }\n    ImVec2 waveform[161];\n    for (int i = 0; i <= 160; ++i)\n    {\n        float t = i / 160.0f;\n        float signal =\n            std::sin(t * 65.0f) * (0.35f + 0.2f * std::sin(t * 17.0f));\n        waveform[i] = ImVec2(\n            p.x + t * size.x, p.y + size.y * (0.5f - signal * 0.65f));\n    }\n    draw->AddPolyline(waveform, 161, IM_COL32(86, 205, 178, 255), 2.0f);\n    float head_x = p.x + cursor_seconds / duration * size.x;\n    draw->AddLine(ImVec2(head_x, p.y),\n        ImVec2(head_x, end.y),\n        IM_COL32(255, 190, 72, 255),\n        2.0f);\n    draw->PopClipRect();\n    ImGui::Text(\"Position: %.3f s %s\",\n        cursor_seconds,\n        dragging ? \"(scrubbing)\" : \"\");\n    ImGui::SliderFloat(\"Time\",\n        &cursor_seconds,\n        0.0f,\n        duration,\n        \"%.3f s\",\n        ImGuiSliderFlags_AlwaysClamp);\n}","id":"visual-time-scrub-section-2","capture":{"guide_id":"visual-time-scrub","section_index":1,"scene":"example-visual-time-scrub-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"069944bf2d47e93229f6241b693fd682cfd1052ae7733cffababffcc5910e6c7","image_sha256":"9f30f60039a8010d71826d6d78b32a28512a0dbdbbd44645f3fd9d0422227951","fixture":"ShowWaveScrubber();","initialization":""}},{"title":"フレーム単位で、イベントの位置も選べるようにする","paragraphs":["映像やアニメーションのイベントは、秒よりフレーム番号で編集したほうが扱いやすい場合があります。次は左クリックで最も近いフレームへ移動し、同じ値をSliderInt()からも操作できる例です。","TimeとFrameのスライダーにはAlwaysClampを付けています。Ctrl+クリックなどで数値を直接入力した場合も範囲内に制限し、再生ヘッドが表示範囲の外へ飛ばないようにします。アプリの別経路から時刻を書き込む場合は、その値にも同じ範囲チェックを行います。"],"code":"void ShowFrameRuler()\n{\n    static int frame = 24;\n    const int last_frame = 120;\n    const float fps = 30.0f;\n    ImVec2 p = ImGui::GetCursorScreenPos();\n    ImVec2 size(std::max(240.0f, ImGui::GetContentRegionAvail().x), 56.0f);\n    ImGui::InvisibleButton(\"frame_ruler\", size);\n    if (ImGui::IsItemActive())\n    {\n        float ratio = std::clamp(\n            (ImGui::GetIO().MousePos.x - p.x) / size.x, 0.0f, 1.0f);\n        frame = static_cast<int>(std::round(ratio * last_frame));\n    }\n    ImDrawList* draw = ImGui::GetWindowDrawList();\n    draw->AddRectFilled(\n        p, ImVec2(p.x + size.x, p.y + size.y), IM_COL32(32, 39, 51, 255));\n    for (int f = 0; f <= last_frame; f += 10)\n    {\n        float x = p.x + size.x * f / last_frame;\n        draw->AddLine(ImVec2(x, p.y + 20),\n            ImVec2(x, p.y + size.y),\n            IM_COL32(111, 128, 150, 255));\n    }\n    float x = p.x + size.x * frame / last_frame;\n    draw->AddLine(ImVec2(x, p.y),\n        ImVec2(x, p.y + size.y),\n        IM_COL32(255, 190, 72, 255),\n        3.0f);\n    ImGui::SliderInt(\n        \"Frame\", &frame, 0, last_frame, \"%d\", ImGuiSliderFlags_AlwaysClamp);\n    ImGui::Text(\"Time: %.3f s at %.1f FPS\", frame / fps, fps);\n}","id":"visual-time-scrub-section-3","capture":{"guide_id":"visual-time-scrub","section_index":2,"scene":"example-visual-time-scrub-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"4238812538d8e76385399f10a5f406c3cdfc50d38ea8329d9976d348a1d6f38b","image_sha256":"c861eee4808b326bc925ce4b2bcb6461e78bcdde793267e89a859cb449899c09","fixture":"ShowFrameRuler();","initialization":""}},{"title":"本物の音声へつなぐときの落とし穴","paragraphs":["長い音声の全サンプルを毎フレーム線にすると、表示幅に対して仕事が多すぎます。1画素に含まれる範囲の最小・最大をまとめて縦線にするなど、表示倍率に合った波形データを用意すると扱いやすくなります。"],"bullets":["シークが重い再生エンジンでは、ドラッグ中は軽いプレビューにし、ボタンを離したタイミングで本シークを行う設計も選べます。InvisibleButtonは値変更通知を持たないため、この例ではIsItemDeactivated()と自分の変更状態を組み合わせます。","音声スレッドのバッファをUIから直接書き換えず、時刻の要求を安全な受け渡し経路で送ります。","時間軸のズーム後も、描画とヒット判定で同じtime-to-screen変換を使います。"],"id":"visual-time-scrub-section-4"},{"title":"トラック編集まで必要になったら","paragraphs":["キーの選択・複数トラック・開始終了の編集が必要なら、ここで作った時間の考え方を保ちつつImSequencerなどの拡張を検討できます。波形を表示すること、選択時刻を保持すること、再生処理を動かすことは、それぞれ別の役目です。"],"id":"visual-time-scrub-section-5"}],"image":"extension-imsequencer","image_scene":"example-visual-time-scrub-02","image_caption":""},{"id":"visual-marquee","title":"ドラッグでまとめて選ぶ、矩形選択を作ってみよう","summary":"配置ツールでおなじみの範囲選択。選択枠を描くところから、点が枠に入ったか調べるところまで、小さく組み立てます。","category":"visuals","level":"advanced","minutes":17,"tags":["矩形選択","複数選択","マウス","座標変換"],"related_api":["ImGui::InvisibleButton","ImGui::IsItemActivated","ImGui::IsItemActive","ImGui::IsItemDeactivated","ImDrawList::AddRect","ImDrawList::AddRectFilled"],"related_guides":["visual-pan-zoom","visual-node-canvas","id-stack"],"sources":[{"title":"v1.93.0 公開API: 座標・入力・DrawList","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"v1.93.0 公式デモ: Custom Rendering / Canvas / Image Viewer","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui_demo.cpp"}],"sections":[{"title":"枠を描く前に、選択のルールを決めよう","paragraphs":["「点が入れば選択」「矩形が少しでも重なれば選択」「物体全体が収まったら選択」では結果が変わります。まずは中心点が入った物体を選ぶ、小さな例から始めます。","ここでは新しいドラッグで選択を置き換えます。Shiftで追加、Ctrlで反転といった仕様は、後からアプリの選択モデルへ足せます。<algorithm> を使い、開いているウィンドウ内で呼びます。"],"id":"visual-marquee-section-1"},{"title":"右下から左上に引いても選べるようにする","paragraphs":["ドラッグの始点が左上とは限りません。2点から毎フレームmin/maxを作り直すのがコツです。ドラッグ状態はIsItemActive()で追い、カーソルが外へ出た場合も選択の操作を続けます。"],"code":"void ShowMarquee()\n{\n    static ImVec2 start;\n    static bool selected[5] = {};\n    const ImVec2 points[] = {ImVec2(55, 60),\n        ImVec2(140, 90),\n        ImVec2(240, 50),\n        ImVec2(100, 170),\n        ImVec2(280, 180)};\n    ImVec2 p = ImGui::GetCursorScreenPos();\n    ImVec2 size(360.0f, 230.0f);\n    ImGui::InvisibleButton(\"marquee\", size);\n    const bool active = ImGui::IsItemActive();\n    if (ImGui::IsItemActivated())\n        start = ImVec2(ImGui::GetIO().MousePos.x - p.x,\n            ImGui::GetIO().MousePos.y - p.y);\n    ImVec2 mouse(\n        ImGui::GetIO().MousePos.x - p.x, ImGui::GetIO().MousePos.y - p.y);\n    ImVec2 lo(std::min(start.x, mouse.x), std::min(start.y, mouse.y));\n    ImVec2 hi(std::max(start.x, mouse.x), std::max(start.y, mouse.y));\n    if (active)\n        for (int i = 0; i < 5; ++i)\n            selected[i] = points[i].x >= lo.x && points[i].x <= hi.x &&\n                          points[i].y >= lo.y && points[i].y <= hi.y;\n    ImDrawList* draw = ImGui::GetWindowDrawList();\n    draw->PushClipRect(p, ImVec2(p.x + size.x, p.y + size.y), true);\n    draw->AddRectFilled(\n        p, ImVec2(p.x + size.x, p.y + size.y), IM_COL32(27, 33, 44, 255));\n    for (int i = 0; i < 5; ++i)\n    {\n        ImVec2 center(p.x + points[i].x, p.y + points[i].y);\n        draw->AddCircleFilled(center,\n            10.0f,\n            selected[i] ? IM_COL32(255, 188, 72, 255)\n                        : IM_COL32(103, 146, 188, 255));\n        if (selected[i])\n            draw->AddText(ImVec2(center.x + 12, center.y - 6),\n                IM_COL32(255, 223, 151, 255),\n                \"selected\");\n    }\n    if (active)\n    {\n        ImVec2 a(p.x + lo.x, p.y + lo.y), b(p.x + hi.x, p.y + hi.y);\n        draw->AddRectFilled(a, b, IM_COL32(84, 165, 255, 45));\n        draw->AddRect(a, b, IM_COL32(105, 184, 255, 255), 0.0f, 1.5f);\n    }\n    draw->PopClipRect();\n    int count = 0;\n    for (bool value : selected)\n        count += value ? 1 : 0;\n    ImGui::Text(\"Selected: %d / 5\", count);\n}","id":"visual-marquee-section-2","capture":{"guide_id":"visual-marquee","section_index":1,"scene":"example-visual-marquee-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"3216579d8a4304bac9e1f225bd4c26666a3f3c5909d6ba6a112e13b58853ac40","image_sha256":"0d617348d69d52aa94d1ed076e8509f19b3918635b0b21cedeafbdbb6a71dfb5","fixture":"ShowMarquee();","initialization":""}},{"title":"ズームしたキャンバスの選択範囲へ戻す","paragraphs":["表示倍率やパンがある場合は、ドラッグの2点を両方ともデータ座標へ戻してから比較します。次の関数はその判定だけを取り出したものです。canvas_originとpanは画面のピクセル単位、objectはデータ座標です。"],"code":"bool IsPointInsideScreenDrag(ImVec2 object,\n    ImVec2 drag_a,\n    ImVec2 drag_b,\n    ImVec2 canvas_origin,\n    ImVec2 pan,\n    float zoom)\n{\n    if (zoom <= 0.0f)\n        return false;\n    ImVec2 a((drag_a.x - canvas_origin.x - pan.x) / zoom,\n        (drag_a.y - canvas_origin.y - pan.y) / zoom);\n    ImVec2 b((drag_b.x - canvas_origin.x - pan.x) / zoom,\n        (drag_b.y - canvas_origin.y - pan.y) / zoom);\n    return object.x >= std::min(a.x, b.x) &&\n           object.x <= std::max(a.x, b.x) &&\n           object.y >= std::min(a.y, b.y) && object.y <= std::max(a.y, b.y);\n}","id":"visual-marquee-section-3","capture":{"guide_id":"visual-marquee","section_index":2,"scene":"example-visual-marquee-03","mode":"result","caption":"掲載関数をサンプル引数で呼び、結果を確認する表示を撮影用に添えています。","backend":"DirectX 11 / WARP","code_sha256":"52691507ba4ab01ae5dbcb6df78b04a957f087d7cf232ba26cc54c65d84abf59","image_sha256":"ac4099ba435cfc20961b6afa90b84497e554bd16130aa94196aa23f802249068","fixture":"ImVec2 origin=ImGui::GetCursorScreenPos(),pan(30,20); const float zoom=1.5f; const ImVec2 a(origin.x+40,origin.y+40),b(origin.x+300,origin.y+220); bool hit=IsPointInsideScreenDrag(ImVec2(100,70),a,b,origin,pan,zoom); ImGui::InvisibleButton(\"Selection result\",ImVec2(500,280)); auto* draw=ImGui::GetWindowDrawList(); draw->AddRect(a,b,IM_COL32(90,170,250,255),0,2); draw->AddCircleFilled(ImVec2(origin.x+pan.x+100*zoom,origin.y+pan.y+70*zoom),8,IM_COL32(255,190,80,255)); ImGui::Text(\"Point (100,70) inside selection: %s\",hit?\"true\":\"false\");","initialization":""}},{"title":"選択枠と、選択されたもののIDを分けて持つ","paragraphs":["始点・終点・ドラッグ中かどうかは一時的な操作状態です。一方で選択結果は、次のフレームやほかのパネルでも使います。配列番号ではなく物体の安定したIDを選択集合へ保存すると、並べ替えや削除にも対応しやすくなります。"],"bullets":["クリックで物体をつかむ操作と、空白で範囲選択を始める操作の優先順位を決めます。","追加選択ではドラッグ開始時の選択集合を保存し、その集合と現在の枠の結果を組み合わせます。前フレームの集合へ反転を繰り返すとちらつきます。","枠だけを描くDrawListには操作IDがありません。物体ごとのドラッグを追加するなら、安定したIDとヒット領域も用意します。"],"id":"visual-marquee-section-4"},{"title":"エディターの選択モデルにつなげよう","paragraphs":["ヒエラルキー・インスペクター・キャンバスが同じ選択IDを参照すれば、どこで選んでも同じ物体を操作できます。範囲選択はその選択モデルを書き換える入力のひとつ、と考えると拡張しやすくなります。"],"id":"visual-marquee-section-5"}],"image":"guide-visual-canvas","image_scene":"example-visual-marquee-02","image_caption":""},{"id":"visual-node-canvas","title":"箱と線で処理の流れを見せる、ノード風キャンバス","summary":"マテリアル、AI、ビルド手順。処理のつながりを見せたいだけなら、まずは箱・ポート・曲線の3つで十分です。小さく描いてから、編集操作を足していきましょう。","category":"visuals","level":"advanced","minutes":20,"tags":["ノード","ベジェ曲線","フロー","キャンバス"],"related_api":["ImGui::GetWindowDrawList","ImGui::InvisibleButton","ImGui::SetCursorScreenPos","ImGui::PushID","ImDrawList::AddBezierCubic","ImDrawList::PushClipRect"],"related_guides":["visual-pan-zoom","visual-marquee","extensions-node-editor"],"sources":[{"title":"v1.93.0 公開API: 描画・スタイル・入力","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"v1.93.0 公式デモ: Custom Rendering / Style Editor","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui_demo.cpp"},{"title":"公式コミュニティ: Dear ImGui tips & trick café!（活用の着想）","url":"https://github.com/ocornut/imgui/issues/7081"}],"sections":[{"title":"「つながりを見せる」と「グラフを編集する」を分けよう","paragraphs":["ノードの表示は、座標を持つ箱と、その間を結ぶ線です。接続の作成・型の互換性・保存・処理の実行は、DrawListが引き受ける機能ではありません。**見た目、入力、グラフデータの役割を分けて**作っていきます。","以下はC++17の <algorithm> を使い、開いているウィンドウ内で呼ぶ例です。各コードは独立しています。"],"id":"visual-node-canvas-section-1"},{"title":"まずは2つのノードを曲線でつなぐ","paragraphs":["3次ベジェ曲線の両端をポートへ置き、制御点を左右に伸ばすと、流れを追いやすい線になります。線を先に、箱を後に描くと、線が箱の上へ重なりにくくなります。"],"code":"void ShowNodePreview()\n{\n    ImVec2 p = ImGui::GetCursorScreenPos();\n    ImVec2 size(500.0f, 220.0f);\n    ImGui::Dummy(size);\n    ImDrawList* draw = ImGui::GetWindowDrawList();\n    draw->PushClipRect(p, ImVec2(p.x + size.x, p.y + size.y), true);\n    draw->AddRectFilled(\n        p, ImVec2(p.x + size.x, p.y + size.y), IM_COL32(25, 31, 42, 255));\n    ImVec2 a(p.x + 24, p.y + 45), b(p.x + 300, p.y + 110);\n    ImVec2 out(a.x + 150, a.y + 42), in(b.x, b.y + 42);\n    draw->AddBezierCubic(out,\n        ImVec2(out.x + 70, out.y),\n        ImVec2(in.x - 70, in.y),\n        in,\n        IM_COL32(110, 192, 255, 255),\n        3.0f);\n    const ImVec2 positions[] = {a, b};\n    const char* names[] = {\"Texture\", \"Material\"};\n    for (int i = 0; i < 2; ++i)\n    {\n        ImVec2 n = positions[i];\n        draw->AddRectFilled(n,\n            ImVec2(n.x + 150, n.y + 76),\n            IM_COL32(47, 59, 76, 255),\n            7.0f);\n        draw->AddRect(n,\n            ImVec2(n.x + 150, n.y + 76),\n            IM_COL32(117, 144, 176, 255),\n            7.0f,\n            1.5f);\n        draw->AddText(ImVec2(n.x + 12, n.y + 12),\n            IM_COL32(239, 244, 255, 255),\n            names[i]);\n    }\n    draw->AddCircleFilled(out, 6.0f, IM_COL32(109, 214, 175, 255));\n    draw->AddCircleFilled(in, 6.0f, IM_COL32(109, 214, 175, 255));\n    draw->PopClipRect();\n}","id":"visual-node-canvas-section-2","capture":{"guide_id":"visual-node-canvas","section_index":1,"scene":"example-visual-node-canvas-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"19b3dcee23ca3c6711a50513360385d61fbec82bf891076badb7502f861456ee","image_sha256":"173f611d9c5fb25c5bd3ea1edf93eba3bf291f533bfa8d52e420b79a26b4e7d2","fixture":"ShowNodePreview();","initialization":""}},{"title":"箱に操作IDを持たせて、ドラッグできるようにする","paragraphs":["ノードごとにInvisibleButton()を置き、安定したIDを割り当てます。これは見た目の箱とは別の入力領域です。位置を更新したあとの値で線と箱を描き直すと、つながりも一緒についてきます。","Dummy()で全体の場所を確保したあと、ノードの位置へカーソルを一時的に移動しています。最後にカーソルを戻すので、次の通常ウィジェットはキャンバスの下へ並びます。","ノードが重なったときは、見た目で上にあるノードが操作を受け取るようにします。この例はノード1を上に描くため、入力領域を1→0の順に登録し、箱は0→1の順に描きます。ノード数や並び順が変わる実装では、配列番号の代わりに各ノードが持つ固定のnode.idをPushID()へ渡してください。"],"code":"void ShowDraggableNodes()\n{\n    static ImVec2 positions[2] = {ImVec2(20, 30), ImVec2(300, 130)};\n    ImVec2 p = ImGui::GetCursorScreenPos();\n    const ImVec2 size(500, 260), node_size(130, 64);\n    ImGui::Dummy(size);\n    ImVec2 after = ImGui::GetCursorScreenPos();\n    ImDrawList* draw = ImGui::GetWindowDrawList();\n    draw->PushClipRect(p, ImVec2(p.x + size.x, p.y + size.y), true);\n    draw->AddRectFilled(\n        p, ImVec2(p.x + size.x, p.y + size.y), IM_COL32(25, 31, 42, 255));\n    // 上に描くノードから入力領域を登録する。\n    for (int i = 1; i >= 0; --i)\n    {\n        ImGui::PushID(i);\n        ImGui::SetCursorScreenPos(\n            ImVec2(p.x + positions[i].x, p.y + positions[i].y));\n        ImGui::InvisibleButton(\"node_drag\", node_size);\n        if (ImGui::IsItemActive() &&\n            ImGui::IsMouseDragging(ImGuiMouseButton_Left))\n        {\n            positions[i].x =\n                std::clamp(positions[i].x + ImGui::GetIO().MouseDelta.x,\n                    0.0f,\n                    size.x - node_size.x);\n            positions[i].y =\n                std::clamp(positions[i].y + ImGui::GetIO().MouseDelta.y,\n                    0.0f,\n                    size.y - node_size.y);\n        }\n        ImGui::PopID();\n    }\n    ImVec2 out(\n        p.x + positions[0].x + node_size.x, p.y + positions[0].y + 32);\n    ImVec2 in(p.x + positions[1].x, p.y + positions[1].y + 32);\n    draw->AddBezierCubic(out,\n        ImVec2(out.x + 65, out.y),\n        ImVec2(in.x - 65, in.y),\n        in,\n        IM_COL32(103, 191, 255, 255),\n        3.0f);\n    // 描画は背面から進め、見た目と入力の優先順位をそろえる。\n    for (int i = 0; i < 2; ++i)\n    {\n        ImVec2 a(p.x + positions[i].x, p.y + positions[i].y);\n        draw->AddRectFilled(a,\n            ImVec2(a.x + node_size.x, a.y + node_size.y),\n            IM_COL32(49, 66, 85, 255),\n            6.0f);\n        draw->AddText(ImVec2(a.x + 12, a.y + 12),\n            IM_COL32(245, 248, 255, 255),\n            i == 0 ? \"Source\" : \"Output\");\n    }\n    draw->AddCircleFilled(out, 6.0f, IM_COL32(112, 225, 174, 255));\n    draw->AddCircleFilled(in, 6.0f, IM_COL32(112, 225, 174, 255));\n    draw->PopClipRect();\n    ImGui::SetCursorScreenPos(after);\n    ImGui::TextUnformatted(\"Drag either node\");\n}","id":"visual-node-canvas-section-3","capture":{"guide_id":"visual-node-canvas","section_index":2,"scene":"example-visual-node-canvas-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"7217ade456d2de6b279c6f83e35799264ea4aa480b54532e6953cb1573880528","image_sha256":"3d230cb1998ce1292f67ca90c1b2bbb132373a64960554cff23737e1f206c4e7","fixture":"ShowDraggableNodes();","initialization":""}},{"title":"線のヒット判定は、線を描くだけでは生まれない","paragraphs":["AddBezierCubic()は描画命令です。クリックで線を選ぶ場合は、曲線を短い線分へ分けてマウスまでの距離を調べるなど、別の判定が必要です。ポートから接続を作る操作も、開始ポートと候補ポートをアプリ側で管理します。"],"bullets":["配列順が変わるグラフでは、PushID(i)のiをノードの永続IDへ置き換えます。","描画クリップと入力領域は別です。この例はノードの位置をキャンバス内へ制限しています。","型違いの接続は線の色だけで伝えず、「float → textureは接続不可」のように理由も表示します。"],"id":"visual-node-canvas-section-4"},{"title":"本格的なノード編集へ進むなら","paragraphs":["この小例は、固定の接続を見せたり、読み取り用の処理グラフを作ったりする入り口に向いています。接続の追加・削除、複数選択、パン・ズームまで必要なら、imgui-node-editorのガイドへ進むと実装範囲を比較できます。","コミュニティのtips & trick caféでは、小さなAPIの組み合わせで用途を広げる例が共有されています。このガイドも既存部品を分解して理解する方針で構成しています。"],"id":"visual-node-canvas-section-5"}],"image":"guide-visual-canvas","image_scene":"example-visual-node-canvas-02","image_caption":""},{"id":"visual-custom-gauges","title":"クールダウンの輪や目盛りゲージを、自分のツールに合わせて描こう","summary":"ProgressBarだけでは伝えにくい残り時間や段階値を、リングと区切り付きゲージで見せてみます。見た目を変えても、数値や操作の意味はわかりやすく残しましょう。","category":"visuals","level":"intermediate","minutes":16,"tags":["ゲージ","リング","クールダウン","カスタムウィジェット"],"related_api":["ImGui::InvisibleButton","ImGui::Dummy","ImDrawList::AddCircle","ImDrawList::PathArcTo","ImDrawList::PathStroke","ImDrawList::AddRectFilled"],"related_guides":["custom-widgets","visual-animation","visual-theme"],"sources":[{"title":"v1.93.0 公開API: 描画・スタイル・入力","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"v1.93.0 公式デモ: Custom Rendering / Style Editor","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui_demo.cpp"},{"title":"公式企画: ImDrawList coding party（図形表現の作例・着想）","url":"https://github.com/ocornut/imgui/issues/3606"}],"sections":[{"title":"割合を0〜1にそろえると、形を変えやすい","paragraphs":["残り時間、体力、ロード進捗は単位が違っても、0〜1の割合に変換すれば描画へ渡せます。**表示する割合は制限し、元の値やエラーは別に残す**と、異常な入力を見た目で隠してしまうのを避けられます。","C++17の <algorithm> と <cmath>、<cstdio> を使います。リングの角度はラジアンです。以下は開いているウィンドウ内で呼びます。"],"id":"visual-custom-gauges-section-1"},{"title":"残り時間をリングと数字で表示する","paragraphs":["下の関数はリング型のクリック領域を持つ部品です。実際のヒット領域は円ではなく90×104の矩形で、戻り値はクリックされたフレームにtrueになります。remainingはアプリが更新して渡してください。","PathStroke()の引数順はv1.93.0の「色、太さ、フラグ」を使っています。古いコードの「色、フラグ、太さ」をそのまま写すと意味が変わるので注意しましょう。"],"code":"bool DrawCooldown(const char* id, float remaining, float duration)\n{\n    const float ratio = duration > 0.0f\n                            ? std::clamp(remaining / duration, 0.0f, 1.0f)\n                            : 0.0f;\n    ImVec2 p = ImGui::GetCursorScreenPos();\n    bool clicked = ImGui::InvisibleButton(id, ImVec2(90.0f, 104.0f));\n    ImVec2 center(p.x + 45, p.y + 43);\n    ImDrawList* draw = ImGui::GetWindowDrawList();\n    draw->AddCircle(center, 33.0f, IM_COL32(70, 80, 96, 255), 0, 7.0f);\n    if (ratio > 0.0f)\n    {\n        const float pi = 3.14159265f;\n        draw->PathArcTo(\n            center, 33.0f, -pi * 0.5f, -pi * 0.5f + ratio * 2.0f * pi);\n        draw->PathStroke(IM_COL32(86, 208, 177, 255), 7.0f);\n    }\n    char text[24];\n    std::snprintf(text, sizeof(text), \"%.1fs\", std::max(0.0f, remaining));\n    ImVec2 text_size = ImGui::CalcTextSize(text);\n    draw->AddText(ImVec2(center.x - text_size.x * 0.5f,\n                      center.y - text_size.y * 0.5f),\n        ImGui::GetColorU32(ImGuiCol_Text),\n        text);\n    draw->AddText(ImVec2(p.x + 12, p.y + 84),\n        ImGui::GetColorU32(ImGuiCol_Text),\n        ratio > 0 ? \"Cooling\" : \"Ready\");\n    if (ImGui::IsItemHovered())\n        ImGui::SetTooltip(\n            \"%s: %.2f / %.2f seconds\", id, remaining, duration);\n    return clicked;\n}","id":"visual-custom-gauges-section-2","capture":{"guide_id":"visual-custom-gauges","section_index":1,"scene":"example-visual-custom-gauges-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"e5f7ba76cddd99acfdb2f9e58fbb6429664e1a884b802e6ac9da50fc004f8831","image_sha256":"5715cf3d53febb458ed8000727bc2689e5de4e2d0f2fd1fb87e108f28b8b3ddd","fixture":"DrawCooldown(\"cooldown\",3.0f,8.0f); ImGui::TextUnformatted(\"Input: 3 seconds remaining / duration 8 seconds\");","initialization":""}},{"title":"10段階の目盛りで、残量をざっくりつかむ","paragraphs":["次は入力を持たない表示専用の部品です。小さな残量でも1目盛り見せるためceil()を使っています。「1目盛り = 必ず10%ちょうど」という表示ではないので、正確な値は数字でも添えます。"],"code":"void DrawSegmentedMeter(float current, float maximum)\n{\n    const float ratio =\n        maximum > 0.0f ? std::clamp(current / maximum, 0.0f, 1.0f) : 0.0f;\n    const int filled = static_cast<int>(std::ceil(ratio * 10.0f));\n    ImVec2 p = ImGui::GetCursorScreenPos();\n    ImGui::Dummy(ImVec2(240.0f, 24.0f));\n    ImDrawList* draw = ImGui::GetWindowDrawList();\n    for (int i = 0; i < 10; ++i)\n    {\n        ImU32 color = i < filled ? IM_COL32(104, 208, 158, 255)\n                                 : IM_COL32(66, 76, 92, 255);\n        draw->AddRectFilled(ImVec2(p.x + i * 24.0f, p.y),\n            ImVec2(p.x + i * 24.0f + 20, p.y + 24),\n            color,\n            3.0f);\n    }\n    ImGui::Text(\"%.1f / %.1f (%.0f%%)\", current, maximum, ratio * 100.0f);\n    if (maximum <= 0.0f)\n        ImGui::TextUnformatted(\"[!] Maximum must be greater than zero\");\n}","id":"visual-custom-gauges-section-3","capture":{"guide_id":"visual-custom-gauges","section_index":2,"scene":"example-visual-custom-gauges-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"ecf20a3bd5e89a026fc841663cfeadb1e0f2b00bae6e0dd4134582b2b7e9587e","image_sha256":"c517aa746c0c66f1cec902f50db4b51e2e7d535c18df91192eeeda3dea7a4c05","fixture":"DrawSegmentedMeter(7.0f,10.0f);","initialization":""}},{"title":"かっこよさと、操作のわかりやすさを両立する","paragraphs":["InvisibleButton()は既定ではキーボードナビゲーションの対象になりません。重要な操作には通常のButton()を併設するか、EnableNavとフォーカス表示を含めて設計しましょう。ツールチップだけに名前を置くと、マウスを乗せるまで意味がわかりません。"],"bullets":["色の変化だけでなくReady/Coolingや残り秒数も表示します。","進捗が不明な仕事に、根拠のない0〜100%を当てはめないようにします。","UIでの補間は見た目の値だけにかけます。実際のクールダウン判定や残量を補間すると、操作のタイミングがずれます。"],"id":"visual-custom-gauges-section-4"},{"title":"自分のツールで、本当に役に立つ形へ","paragraphs":["リングは残り時間、横長バーは量の比較、目盛りは段階の把握が得意です。公式のImDrawList coding partyには図形だけで表現を広げた作例が集まっています。形の着想を得つつ、普段使うツールでは読める数値・名前・操作状態も残してみてください。"],"id":"visual-custom-gauges-section-5"}],"image":"guide-visual-dashboard","image_scene":"example-visual-custom-gauges-02","image_caption":""},{"id":"visual-atlas-viewer","title":"スプライトを選んで切り出す、UVとアトラスのビューアー","summary":"1枚の画像に並んだアイコンやスプライトから、使う範囲を選べるようにします。画像サイズ、表示サイズ、UVの違いがわかると、素材を見るツールを作りやすくなります。","category":"visuals","level":"advanced","minutes":19,"tags":["画像","UV","アトラス","スプライト","テクスチャ"],"related_api":["ImGui::Image","ImGui::ImageButton","ImGui::GetItemRectMin","ImGui::GetItemRectMax","ImGui::IsItemHovered","ImDrawList::AddRect"],"related_guides":["image-texture","image-dx11","image-dx12","visual-pan-zoom"],"sources":[{"title":"v1.93.0 公開API: 描画・スタイル・入力","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"v1.93.0 公式デモ: Custom Rendering / Style Editor","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui_demo.cpp"}],"sections":[{"title":"渡すのはファイル名ではなく、GPUで読める画像の参照","paragraphs":["この例のtextureには、描画バックエンドが使えるImTextureRefを渡します。DX11ならSRVの参照、DX12なら適切なshader-visibleヒープにあるSRVのGPUディスクリプターハンドルをImTextureIDへ変換し、ImTextureRefで包みます。具体的な作成・寿命・同期はDX11/DX12のガイドで確認できます。","width/heightは元画像のピクセル数です。**画面上で何ピクセルに見せるかと、画像のどの範囲を読むかは別**です。以下は <algorithm> を使い、開いているウィンドウ内で呼びます。"],"id":"visual-atlas-viewer-section-1"},{"title":"アトラスをクリックして、64×64のセルを選ぶ","paragraphs":["クリック位置を0〜1へ変換し、列と行に置き換えます。選んだセルは黄色い枠で示し、下に拡大表示します。Image()の枠線を0にしておくと、アイテム矩形と画像の表示範囲を一致させられます。","この例は幅・高さが64の倍数の等間隔アトラスを対象とします。余白やセル間の隙間がある画像には、別途その分を差し引く計算が必要です。"],"code":"void ShowAtlasSelector(ImTextureRef texture, int width, int height)\n{\n    if (width < 64 || height < 64 || width % 64 != 0 || height % 64 != 0)\n    {\n        ImGui::TextUnformatted(\n            \"Use an atlas whose dimensions are multiples of 64\");\n        return;\n    }\n    static int selected = 0;\n    const int columns = width / 64, rows = height / 64;\n    selected = std::clamp(selected, 0, columns * rows - 1);\n    float scale = std::min(320.0f / width, 240.0f / height);\n    ImGui::PushStyleVar(ImGuiStyleVar_ImageBorderSize, 0.0f);\n    ImGui::Image(texture, ImVec2(width * scale, height * scale));\n    ImGui::PopStyleVar();\n    ImVec2 p = ImGui::GetItemRectMin(), end = ImGui::GetItemRectMax();\n    if (ImGui::IsItemHovered() &&\n        ImGui::IsMouseClicked(ImGuiMouseButton_Left))\n    {\n        ImVec2 mouse = ImGui::GetIO().MousePos;\n        int column = std::clamp(\n            static_cast<int>((mouse.x - p.x) / (end.x - p.x) * columns),\n            0,\n            columns - 1);\n        int row = std::clamp(\n            static_cast<int>((mouse.y - p.y) / (end.y - p.y) * rows),\n            0,\n            rows - 1);\n        selected = row * columns + column;\n    }\n    int column = selected % columns, row = selected / columns;\n    ImVec2 uv0(column / static_cast<float>(columns),\n        row / static_cast<float>(rows));\n    ImVec2 uv1((column + 1) / static_cast<float>(columns),\n        (row + 1) / static_cast<float>(rows));\n    ImGui::GetWindowDrawList()->AddRect(\n        ImVec2(p.x + uv0.x * (end.x - p.x), p.y + uv0.y * (end.y - p.y)),\n        ImVec2(p.x + uv1.x * (end.x - p.x), p.y + uv1.y * (end.y - p.y)),\n        IM_COL32(255, 196, 78, 255),\n        0.0f,\n        2.0f);\n    ImGui::Text(\"Cell %d / UV (%.3f, %.3f) - (%.3f, %.3f)\",\n        selected,\n        uv0.x,\n        uv0.y,\n        uv1.x,\n        uv1.y);\n    ImGui::Image(texture, ImVec2(128, 128), uv0, uv1);\n}","id":"visual-atlas-viewer-section-2","capture":{"guide_id":"visual-atlas-viewer","section_index":1,"scene":"example-visual-atlas-viewer-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"ede22242b9e9463f9b55b4004c9ebf3dbcb3e1d0d495b18a08584596745fcb2f","image_sha256":"f9f5ae5b0c6fca79703ca052665ac51bc9897d3d1e8495356e502d19df0b4113","fixture":"ShowAtlasSelector(Texture(),256,256);","initialization":""}},{"title":"任意のピクセル範囲を、UVへ変換してみる","paragraphs":["等間隔でない素材には、切り出し位置と幅・高さを渡すほうが便利です。次の関数は範囲を画像内へ制限し、UVへ変換してImage()に渡します。戻り値trueは有効な切り出し範囲を表示できた、という意味です。"],"code":"bool ShowPixelCrop(ImTextureRef texture,\n    int texture_width,\n    int texture_height,\n    int x,\n    int y,\n    int crop_width,\n    int crop_height)\n{\n    if (texture_width <= 0 || texture_height <= 0 || crop_width <= 0 ||\n        crop_height <= 0)\n        return false;\n    x = std::clamp(x, 0, texture_width - 1);\n    y = std::clamp(y, 0, texture_height - 1);\n    crop_width = std::min(crop_width, texture_width - x);\n    crop_height = std::min(crop_height, texture_height - y);\n    ImVec2 uv0(x / static_cast<float>(texture_width),\n        y / static_cast<float>(texture_height));\n    ImVec2 uv1((x + crop_width) / static_cast<float>(texture_width),\n        (y + crop_height) / static_cast<float>(texture_height));\n    ImGui::Text(\n        \"Crop: %d, %d / %d x %d pixels\", x, y, crop_width, crop_height);\n    ImGui::Image(\n        texture, ImVec2(crop_width * 2.0f, crop_height * 2.0f), uv0, uv1);\n    return true;\n}","id":"visual-atlas-viewer-section-3","capture":{"guide_id":"visual-atlas-viewer","section_index":2,"scene":"example-visual-atlas-viewer-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"3b30e0bdde27e29762e89dc3f09c76cc556aed05ab1a41fbdb6f9bbf640e9ee2","image_sha256":"829192e5cde98d33aa4db8a1291734359db5eea65a026f750d05c7693738d570","fixture":"ShowPixelCrop(Texture(),256,256,64,64,128,96);","initialization":""}},{"title":"ぼやける、裏返る、隣のセルがにじむ。何を見直す？","paragraphs":["見た目の問題はUVだけが原因とは限りません。元の画像、サンプラー、テクスチャの登録、バックエンドの設定を順に切り分けましょう。"],"table":{"headers":["症状","まず確認すること"],"rows":[["ピクセル絵がぼやける","線形補間のサンプラーか。整数倍率やpoint/nearestの設定が必要か"],["隣のセルの色が混ざる","アトラスのパディング、ミップマップ、フィルターがセル境界をまたいでいないか"],["上下が逆","画像の取り込み方とUV原点。必要ならuv0.yとuv1.yを入れ替える"],["白い四角や別の画像が出る","有効なGPU参照か。DX12ではSRVとバインドしているヒープが対応しているか"],["画像を閉じたあとに不安定","描画が完了する前にGPUリソースやディスクリプターを解放していないか"]]},"id":"visual-atlas-viewer-section-4"},{"title":"素材ブラウザーやアニメーションプレビューへ広げる","paragraphs":["セルのIDとUV範囲をアプリの素材データへ保存すれば、スプライトの選択ツールになります。連続するセルを時間で切り替えればアニメーションプレビューにも使えます。テクスチャ参照そのものは実行環境で変わるため、保存データには素材パスや独自IDを使いましょう。"],"id":"visual-atlas-viewer-section-5"}],"image":"image","image_scene":"example-visual-atlas-viewer-02","image_caption":""},{"id":"visual-theme","title":"テーマを変えても読めるUIへ。色・余白・状態の整え方","summary":"ダークにしたら警告が読みにくい、ボタンが無効なのかわからない。色の一覧を触る前に、何をどう見分けたいかを決めて、スタイルを整えてみましょう。","category":"visuals","level":"intermediate","minutes":15,"tags":["テーマ","スタイル","配色","アクセシビリティ"],"related_api":["ImGui::StyleColorsDark","ImGui::StyleColorsLight","ImGui::PushStyleColor","ImGui::PushStyleVar","ImGui::BeginDisabled","ImGui::ShowStyleEditor"],"related_guides":["visual-hud","visual-custom-gauges","recipes-help-feedback","basics-keyboard-nav"],"sources":[{"title":"v1.93.0 公開API: 描画・スタイル・入力","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"v1.93.0 公式デモ: Custom Rendering / Style Editor","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui_demo.cpp"}],"sections":[{"title":"色の名前より、役割を先に決める","paragraphs":["「緑なら成功」だけでは、文字が読めない場面や色の区別が難しい場面で意味が伝わりません。**状態名・アイコン代わりの記号・色を組み合わせる**と、テーマが変わっても理解しやすくなります。","テーマ全体の初期化は起動時やユーザーが変更したタイミングで行います。毎フレームStyleColorsDark()を呼ぶと、ユーザーの調整を毎回消してしまいます。"],"id":"visual-theme-section-1"},{"title":"標準テーマを土台にして、少しだけ整える","paragraphs":["ここでは色の数をむやみに増やさず、角丸・余白・枠線を調整しています。関数は起動時、またはテーマの切り替え時に呼びます。フォントやUIスケールまで毎回変える処理は含めていません。"],"code":"void ApplyReadableTheme(bool dark)\n{\n    if (dark)\n        ImGui::StyleColorsDark();\n    else\n        ImGui::StyleColorsLight();\n    ImGuiStyle& style = ImGui::GetStyle();\n    style.FramePadding = ImVec2(8.0f, 5.0f);\n    style.ItemSpacing = ImVec2(9.0f, 7.0f);\n    style.WindowPadding = ImVec2(12.0f, 12.0f);\n    style.FrameRounding = 5.0f;\n    style.WindowRounding = 7.0f;\n    style.FrameBorderSize = 1.0f;\n    style.Colors[ImGuiCol_Border] = dark\n                                        ? ImVec4(0.39f, 0.43f, 0.50f, 1.0f)\n                                        : ImVec4(0.48f, 0.51f, 0.56f, 1.0f);\n    style.Colors[ImGuiCol_Text] = dark ? ImVec4(0.94f, 0.95f, 0.98f, 1.0f)\n                                       : ImVec4(0.09f, 0.10f, 0.13f, 1.0f);\n}","id":"visual-theme-section-2","capture":{"guide_id":"visual-theme","section_index":1,"scene":"example-visual-theme-02","mode":"result","caption":"掲載関数をサンプル引数で呼び、結果を確認する表示を撮影用に添えています。","backend":"DirectX 11 / WARP","code_sha256":"ff4a3f59abcb045845333f6ba0395c50af0c38a8f89c46270102f11e78a041d4","image_sha256":"f0bf06fcf8912772efd9699b2f9c98ba8a8c91579a8dd24535910d55c310dd14","fixture":"ApplyReadableTheme(true); static float gain=0.6f; static bool enabled=true; ImGui::TextUnformatted(\"Theme applied by ApplyReadableTheme(true)\"); ImGui::Checkbox(\"Enabled\",&enabled); ImGui::SliderFloat(\"Gain\",&gain,0,1); ImGui::Button(\"Primary action\");","initialization":""}},{"title":"重要な操作と、実行できない理由を並べる","paragraphs":["PushStyleColor()/PushStyleVar()は局所的な見た目の変更に使います。無効にしたボタンのそばへ理由を常に表示すると、ホバーしないと何もわからない画面を避けられます。","この例は保存処理の代わりに要求フラグを更新します。save_requestedを受け取ったアプリ側が、実際の保存を担当します。"],"code":"void ShowSaveActions(bool document_changed, bool& save_requested)\n{\n    ImGui::TextUnformatted(document_changed ? \"[EDITED] Unsaved changes\"\n                                            : \"[OK] All changes saved\");\n    ImGui::BeginDisabled(!document_changed);\n    ImGui::PushStyleVar(ImGuiStyleVar_FrameRounding, 5.0f);\n    ImGui::PushStyleColor(\n        ImGuiCol_Button, ImVec4(0.08f, 0.37f, 0.28f, 1.0f));\n    ImGui::PushStyleColor(\n        ImGuiCol_ButtonHovered, ImVec4(0.10f, 0.47f, 0.35f, 1.0f));\n    ImGui::PushStyleColor(\n        ImGuiCol_ButtonActive, ImVec4(0.05f, 0.29f, 0.22f, 1.0f));\n    ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(1, 1, 1, 1));\n    if (ImGui::Button(\"Save changes\"))\n        save_requested = true;\n    ImGui::PopStyleColor(4);\n    ImGui::PopStyleVar();\n    ImGui::EndDisabled();\n    if (!document_changed)\n        ImGui::TextUnformatted(\"No changes to save\");\n    ImGui::TextUnformatted(\"Save writes the document to its current file.\");\n}","id":"visual-theme-section-3","capture":{"guide_id":"visual-theme","section_index":2,"scene":"example-visual-theme-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"2528cbeed9f8575b6ba02a8e1e088c6ec27d2c9327608eeb6019b5893e83217b","image_sha256":"da42168aca889607837d4637e77ad96868c9138a7807b8f9c1cd77a1fe2ddd23","fixture":"static bool requested=false; ShowSaveActions(true,requested);","initialization":""}},{"title":"Style Editorは、テーマの実験台として使おう","paragraphs":["ShowStyleEditor()を自分のツールに置くと、スタイルの値をその場で試せます。完成した値は自分の初期化処理へ反映します。Style Editorを開くことと、アプリの設定としてテーマを保存することは別です。"],"bullets":["明暗の両方で通常・ホバー・押下・無効・選択の状態を確認します。","通常文字と背景だけでなく、入力枠や選択範囲の境界が見えるかも確認します。","文字を大きくするときはフォント・DPIと余白の関係も見ます。ScaleAllSizes()を毎フレーム掛け続けないようにします。","注意を赤にする場合も、何が起きたかを文章で補います。すべてを強調すると大事な場所が埋もれます。"],"id":"visual-theme-section-4"},{"title":"自分用設定として、好みを残す","paragraphs":["明暗テーマ・文字サイズ・動きを減らす設定などをアプリの設定データへ保存すると、次回も同じ見え方で使えます。ImGuiの.iniはウィンドウ配置などの保存に使われますが、アプリ独自のテーマ選択を何でも自動保存する機能ではありません。"],"id":"visual-theme-section-5"}],"image":"showstyleeditor","image_scene":"example-visual-theme-02","image_caption":""},{"id":"visual-animation","title":"ふわっと変わるUIにする。時間に合わせた補間とアニメーション","summary":"表示値が切り替わるときに、少しだけ動きを足してみます。速さがPCのFPSに左右されないようにし、動きを減らしたい人の設定も用意しましょう。","category":"visuals","level":"advanced","minutes":17,"tags":["アニメーション","DeltaTime","補間","状態管理"],"related_api":["ImGui::GetIO","ImGui::GetTime","ImGui::ProgressBar","ImGui::Checkbox","ImGui::PushID"],"related_guides":["visual-custom-gauges","visual-hud","frame-state","recipes-help-feedback"],"sources":[{"title":"v1.93.0 公開API: 描画・スタイル・入力","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"v1.93.0 公式デモ: Custom Rendering / Style Editor","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui_demo.cpp"},{"title":"公式企画: ImDrawList coding party（時間を使った表現の着想）","url":"https://github.com/ocornut/imgui/issues/3606"}],"sections":[{"title":"データを動かすのか、見た目だけ動かすのか決める","paragraphs":["処理が完了した事実を、バーのアニメーションが終わるまで待たせる必要はありません。**本当の状態と表示用の値を分ける**と、見た目を滑らかにしながら正しい判断もできます。","以下はC++17の <algorithm> と <cmath> を使います。開いているウィンドウ内で毎フレーム呼びます。動きを減らす設定はアプリが保持するboolです。ImGuiがOSの設定を自動で反映するわけではありません。"],"id":"visual-animation-section-1"},{"title":"表示用の値だけ、目的値へなめらかに近づける","paragraphs":["1フレームに一定量を足すと、FPSが高いほど速く動きます。ここではDeltaTimeから指数補間の係数を求めます。targetは即座に変わり、shownはそれを追いかけます。","指数補間は少しずつ近づく式なので、十分近くなったら目的値へそろえています。計測値や進捗そのものを書き換えないことがポイントです。","この例の実進捗は0〜1を前提にしているため、スライダーの直接入力にもAlwaysClampを付けています。実際の計測処理やジョブ処理から受け取る値は、UIのフラグに頼らずアプリ側でも確認してください。"],"code":"void ShowSmoothProgress()\n{\n    static float target = 0.25f;\n    static float shown = 0.25f;\n    static bool reduce_motion = false;\n    ImGui::Checkbox(\"Reduce motion\", &reduce_motion);\n    ImGui::SliderFloat(\"Actual progress\",\n        &target,\n        0.0f,\n        1.0f,\n        \"%.3f\",\n        ImGuiSliderFlags_AlwaysClamp);\n    float dt = std::max(0.0f, ImGui::GetIO().DeltaTime);\n    float blend = reduce_motion ? 1.0f : 1.0f - std::exp(-12.0f * dt);\n    shown += (target - shown) * blend;\n    if (std::abs(target - shown) < 0.0001f)\n        shown = target;\n    ImGui::ProgressBar(shown, ImVec2(-1, 0), \"Visual progress\");\n    ImGui::Text(\n        \"Actual: %.0f%% / shown: %.0f%%\", target * 100, shown * 100);\n    if (target >= 1.0f)\n        ImGui::TextUnformatted(\"[DONE] Work has completed\");\n}","id":"visual-animation-section-2","capture":{"guide_id":"visual-animation","section_index":1,"scene":"example-visual-animation-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"546ac70f7f76f56391d3ad492f918968124c950347323ce0c8280495b365afba","image_sha256":"6412c1edbe86a125005c88e939bf9da6aadbaa50bc82c417bcb9e9acc756acae","fixture":"ShowSmoothProgress();","initialization":""}},{"title":"時間を決めて、完了後の通知をフェードさせる","paragraphs":["時間が決まっている動きには、開始時刻と現在時刻の差を使う方法が向いています。下の例はボタンを押すたびに通知を1.8秒表示し、最後の0.6秒だけ薄くします。","動きを減らす設定では、途中のフェードをなくして、一定時間そのまま読める表示にしています。成功や失敗の重要情報を、短いアニメーションの中だけに閉じ込めないようにしましょう。"],"code":"void ShowFadingNotice(bool reduce_motion)\n{\n    static double started = -100.0;\n    const double now = ImGui::GetTime();\n    if (ImGui::Button(\"Show notice\"))\n        started = now;\n    float age = static_cast<float>(now - started);\n    if (age >= 0.0f && age < 1.8f)\n    {\n        float fade = reduce_motion\n                         ? 1.0f\n                         : std::clamp((1.8f - age) / 0.6f, 0.0f, 1.0f);\n        ImVec4 color = ImGui::GetStyleColorVec4(ImGuiCol_Text);\n        color.w *= fade;\n        ImGui::TextColored(color, \"%s\", \"[OK] Preview updated\");\n    }\n    ImGui::TextUnformatted(\n        \"The preview state remains available after this notice disappears.\");\n}","id":"visual-animation-section-3","capture":{"guide_id":"visual-animation","section_index":2,"scene":"example-visual-animation-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"cea85ac04c3fc636557cb18bcaac8f2249d2ae304fb84864fb4f4e9de7aac0fb","image_sha256":"7b94387ad20e24845b679664bd0944f09810086fb992368d31eddde2e1280f9f","fixture":"ShowFadingNotice(false);","initialization":""}},{"title":"同じ部品を複数置くなら、アニメーション状態も分ける","paragraphs":["この例のstaticは、ひとつだけ置くサンプル用です。同じ関数を複数回呼んでもstaticは共有されるので、アニメーションまで同期してしまいます。実際の部品は表示用の値と開始時刻を構造体にし、部品ごとの安定IDに対応させて保持しましょう。"],"bullets":["PushID()はアニメーション用変数を自動で作り分けません。IDとアプリの状態は別に用意します。","非表示の間も進む通知ならGetTime()基準、表示している間だけ更新したい値なら自分の時間管理を選びます。","停止やフレーム落ちでDeltaTimeが大きくなった場合の動きを確認します。見た目用にdtを制限すると、実時間に追いつく速さは変わります。","点滅や揺れを常時かけるより、短い状態変化に絞るほうが読み取りを邪魔しにくくなります。"],"id":"visual-animation-section-4"},{"title":"動きは「変わった場所」を伝えるために使う","paragraphs":["警告の意味、入力のフォーカス、現在の値は、アニメーションなしでも読める状態にします。そのうえで少し動きを足すと、更新された場所を追いやすくなります。図形表現の作例から着想を得る場合も、ツールで長時間見る情報には速度や頻度の調整を用意しましょう。"],"id":"visual-animation-section-5"}],"image":"guide-visual-dashboard","image_scene":"example-visual-animation-02","image_caption":""}]);
